import * as THREE from 'three';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

/**
 * Export Three.js scene to OBJ format with Blender Z-up conversion
 */

class OBJExporter {
  constructor() {
    this.vertexIndex = 1; // OBJ indices start at 1
    this.output = '';
    this.vertices = [];
    this.faces = [];
  }

  /**
   * Convert Three.js geometry to OBJ format
   * Applies -90 degree X-rotation for Blender Z-up space
   */
  exportScene(scene) {
    this.output = '# Exported from Three.js to Blender Z-up space\n';
    this.output += '# -90 degree X-rotation applied\n\n';

    // Create rotation matrix for -90 degrees around X-axis
    const rotationMatrix = new THREE.Matrix4();
    rotationMatrix.makeRotationX(-Math.PI / 2);

    // Traverse the scene and export all meshes
    scene.traverse((object) => {
      if (object.isMesh || object.isInstancedMesh) {
        this.exportMesh(object, rotationMatrix);
      }
    });

    return this.output;
  }

  /**
   * Export a single mesh to OBJ format
   */
  exportMesh(mesh, rotationMatrix) {
    const geometry = mesh.geometry;

    if (!geometry) return;

    // Clone geometry to avoid modifying original
    const geo = geometry.clone();

    // Ensure geometry has position attribute
    if (!geo.attributes.position) return;

    // Handle InstancedMesh separately
    if (mesh.isInstancedMesh) {
      this.exportInstancedMesh(mesh, rotationMatrix);
      return;
    }

    // Get world matrix for this mesh
    mesh.updateMatrixWorld(true);
    const worldMatrix = mesh.matrixWorld.clone();

    // Apply world matrix then rotation
    geo.applyMatrix4(worldMatrix);
    geo.applyMatrix4(rotationMatrix);

    // Write object/group name
    this.output += `o ${mesh.name || 'mesh'}\n`;

    // Get position attribute
    const positions = geo.attributes.position;
    const startVertex = this.vertexIndex;

    // Write vertices
    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i);
      const y = positions.getY(i);
      const z = positions.getZ(i);
      this.output += `v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
    }

    // Write faces
    if (geo.index) {
      // Indexed geometry
      const indices = geo.index.array;
      for (let i = 0; i < indices.length; i += 3) {
        const a = startVertex + indices[i];
        const b = startVertex + indices[i + 1];
        const c = startVertex + indices[i + 2];
        this.output += `f ${a} ${b} ${c}\n`;
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positions.count; i += 3) {
        const a = startVertex + i;
        const b = startVertex + i + 1;
        const c = startVertex + i + 2;
        this.output += `f ${a} ${b} ${c}\n`;
      }
    }

    this.vertexIndex += positions.count;
    this.output += '\n';
  }

  /**
   * Export instanced mesh (used for axis pins)
   */
  exportInstancedMesh(instancedMesh, rotationMatrix) {
    const geometry = instancedMesh.geometry;
    const count = instancedMesh.count;

    if (!geometry || !geometry.attributes.position) return;

    const tempMatrix = new THREE.Matrix4();

    for (let i = 0; i < count; i++) {
      // Get instance matrix
      instancedMesh.getMatrixAt(i, tempMatrix);

      // Clone geometry for this instance
      const geo = geometry.clone();

      // Get world matrix
      instancedMesh.updateMatrixWorld(true);
      const worldMatrix = instancedMesh.matrixWorld.clone();
      worldMatrix.multiply(tempMatrix);

      // Apply transformations
      geo.applyMatrix4(worldMatrix);
      geo.applyMatrix4(rotationMatrix);

      // Write object name
      this.output += `o ${instancedMesh.name}_instance_${i}\n`;

      // Get position attribute
      const positions = geo.attributes.position;
      const startVertex = this.vertexIndex;

      // Write vertices
      for (let j = 0; j < positions.count; j++) {
        const x = positions.getX(j);
        const y = positions.getY(j);
        const z = positions.getZ(j);
        this.output += `v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
      }

      // Write faces
      if (geo.index) {
        const indices = geo.index.array;
        for (let j = 0; j < indices.length; j += 3) {
          const a = startVertex + indices[j];
          const b = startVertex + indices[j + 1];
          const c = startVertex + indices[j + 2];
          this.output += `f ${a} ${b} ${c}\n`;
        }
      } else {
        for (let j = 0; j < positions.count; j += 3) {
          const a = startVertex + j;
          const b = startVertex + j + 1;
          const c = startVertex + j + 2;
          this.output += `f ${a} ${b} ${c}\n`;
        }
      }

      this.vertexIndex += positions.count;
      this.output += '\n';
    }
  }
}

// Main execution
function main() {
  // Create the scene
  const scene = createScene();

  // Update all world matrices
  scene.updateMatrixWorld(true);

  // Export to OBJ
  const exporter = new OBJExporter();
  const objContent = exporter.exportScene(scene);

  // Ensure output directory exists
  const outputDir = '/root/output';
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write OBJ file
  const outputPath = path.join(outputDir, 'object.obj');
  fs.writeFileSync(outputPath, objContent, 'utf8');

  console.log(`Successfully exported to ${outputPath}`);
  console.log(`Total vertices: ${exporter.vertexIndex - 1}`);
}

main();

